const COOKIE = '__Host-sid';
export const IDLE_MS = 30 * 60_000;
export const ABSOLUTE_MS = 12 * 60 * 60_000;

export function createSession(userId: string, aal: Aal): Session {
  const id = randomBytes(32).toString('base64url');
  sessions.set(id, { userId, aal, createdAt: Date.now(), lastSeenAt: Date.now() });
  return { id, cookie: `${COOKIE}=${id}; Path=/; HttpOnly; Secure; SameSite=Lax` };
}

/** Replace the id at every privilege boundary; the old id is dead immediately. */
export function rotateSession(old: string, aal: Aal): Session {
  const prev = sessions.get(old);
  sessions.delete(old);
  if (!prev) throw new Unauthorized('session expired');
  audit({ actor: prev.userId, action: 'session.rotate', target: `aal:${aal}` });
  return createSession(prev.userId, aal);
}

